export interface JsonElementScan extends IterateJsonArrayResult {
    status: number;
}

function emptyScan(status: number): JsonElementScan {
    return {
        status,
        bytes: 0,
        items: 0,
        skipped: 0,
        truncatedStrings: 0,
        maxBufferChars: 0,
        foundArray: false,
        complete: true,
        stopped: false,
        html: false,
    };
}

async function readCapped(res: Response, max: number): Promise<string> {
    if (!res.body) return '';
    const reader = res.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        total += value.length;
        if (total >= max) {
            await reader.cancel();
            throw new HttpError(`Response larger than ${max} bytes`, 'RESPONSE_TOO_LARGE', false);
        }
    }
    return new TextDecoder('utf-8', { fatal: false }).decode(Buffer.concat(chunks));
}

function errText(e: unknown): string {
    if (!(e instanceof Error)) return String(e);
    const code = (e as { cause?: { code?: string } }).cause?.code;
    return code ? `${e.message} (${code})` : e.message;
}

type FetchKind = 'robots' | 'xml' | 'page' | 'pinpoint' | 'gem';

function looksLikeHtml(body: string): boolean {
    const t = body.trimStart().slice(0, 200).toLowerCase();
    return t.startsWith('<!doctype html') || t.startsWith('<html') || /<\s*html[\s>]/i.test(t);
}

